def _process_description_content_type(self, value: str) -> str:
    content_types = {"text/plain", "text/x-rst", "text/markdown"}
    message = email.message.EmailMessage()
    # Assigning the value can raise for badly formed content types (e.g. a
    # header containing a linefeed or a malformed parameter), so make sure
    # those never leak out as a raw, confusing error.
    try:
        message["content-type"] = value
        content_type, parameters = (
            # Defaults to `text/plain` if parsing failed.
            message.get_content_type().lower(),
            message["content-type"].params,
        )
    except (ValueError, IndexError) as exc:
        raise self._invalid_metadata(
            f"{value!r} is not a valid content type for {self.raw_name!r}",
            cause=exc,
        ) from exc

    # Some malformed values parse without raising but are still flagged with
    # defects (e.g. a parameter with no value); treat those as invalid too.
    if message["content-type"].defects:
        raise self._invalid_metadata(
            f"{value!r} is not a valid content type for {self.raw_name!r}"
        )

    # Check if content-type is valid or defaulted to `text/plain` and thus was
    # not parseable.
    if content_type not in content_types or content_type not in value.lower():
        raise self._invalid_metadata(
            f"{self.raw_name!r} must be one of {list(content_types)}, not {value!r}"
        )

